import{_ as t,c as s,o as p,ah as o,ao as a,ap as i}from"./chunks/framework.Dq2_gudl.js";const b=JSON.parse('{"title":"اجازه داشتن برای اندوه — خدا اشک‌های شما را در ظرفی نگه می‌دارد","description":"گریه برای حیوان خانگی نشانه کم‌بودن ایمان نیست. مزامیر می‌گوید خدا اشک‌های ما را در ظرفی جمع می‌کند و در کتابش ثبت می‌کند.","frontmatter":{"title":"اجازه داشتن برای اندوه — خدا اشک‌های شما را در ظرفی نگه می‌دارد","description":"گریه برای حیوان خانگی نشانه کم‌بودن ایمان نیست. مزامیر می‌گوید خدا اشک‌های ما را در ظرفی جمع می‌کند و در کتابش ثبت می‌کند."},"headers":[],"relativePath":"fa/pets-in-heaven/permission-to-grieve.md","filePath":"fa/pets-in-heaven/permission-to-grieve.md"}'),n={name:"fa/pets-in-heaven/permission-to-grieve.md"};function l(c,e,r,h,m,d){return p(),s("div",null,[...e[0]||(e[0]=[o('<div class="pl-quote"><p>«ماه‌ها گذشته و من هنوز گریه می‌کنم. آیا به‌قدر کافی قوی نیستم؟ آیا ایمانم کوچک است؟»</p><p class="pl-quote-soft">کتاب مقدس هرگز اشک را نشانه شکست ندانسته است. کاملاً برعکس.</p></div><section class="pl-section"><h2>۱. خدا اشک‌ها را در ظرفی نگه می‌دارد</h2><blockquote><p><strong>مزامیر ۵۶:۸</strong></p><p>&quot;Thou tellest my wanderings: put thou my tears into thy bottle: are they not in thy book?&quot;</p></blockquote><p>داوود این را از عمق رنج نوشت. او از خدا می‌خواهد اشک‌هایش را در ظرفی بگذارد و در کتابی ثبت کند — در جهان باستان، ظرف اشک مجموعه‌ای گران‌بها بود، گواهی بر اینکه «این شخص برای این چیز گریه کرد».</p><p>معنایش این است: <strong>اشک‌های شما چیزی نیست که بریزد و ناپدید شود.</strong> حتی یک قطره هدر نمی‌رود. هر اشکی که برای او ریختید جمع می‌شود. ثبت می‌شود.</p><p>پس وقتی فکر می‌کنید «نکند زیادی گریه می‌کنم»، به یاد داشته باشید: برای خدا این سر و صدا نیست. این یک ثبت است.</p></section><section class="pl-section"><h2>۲. خدا به شکسته‌دلان نزدیک می‌شود — آن‌ها را سرزنش نمی‌کند</h2><blockquote><p><strong>مزامیر ۳۴:۱۸</strong></p><p>&quot;The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.&quot;</p></blockquote><blockquote><p><strong>مزامیر ۱۴۷:۳</strong></p><p>&quot;He healeth the broken in heart, and bindeth up their wounds.&quot;</p></blockquote><p>به فعل‌ها توجه کنید: او <em>نزدیک می‌شود</em>. او <em>شفا می‌دهد</em>. او <em>زخم را می‌بندد</em>. نخستین کاری که خدا برای داغدار می‌کند این نیست که بخواهد خود را جمع‌وجور کند — بلکه به سوی او می‌آید.</p><p>عیسی نیز جمله‌ای کوتاه گفت:</p><blockquote><p><strong>متی ۵:۴</strong></p><p>&quot;Blessed are they that mourn: for they shall be comforted.&quot;</p></blockquote><p>«خوشا به حال ماتم‌داران.» داغداران سرزنش نمی‌شوند — بلکه خوشا به حالشان خوانده می‌شوند، چون تسلی می‌آید. نه «باید خوشحال شوی»، بلکه «تسلی خواهی یافت».</p></section><section class="pl-section"><h2>۳. اندوه نقطه مقابل عشق نیست — ادامه عشق است</h2><p>ما برای چیزی که هرگز دوست نداشتیم گریه نمی‌کنیم. دلیل این‌همه درد این است که واقعاً میان شما عشق بود.</p><p>خدا ما را موجوداتی ساخت که برای از دست دادن گریه می‌کنند. خود عیسی نیز بر سر مقبره ایلعازر گریه کرد (یوحنا ۱۱:۳۵) — با آنکه می‌دانست چند دقیقه بعد او را زنده می‌کند، باز گریه کرد.</p><p>پس لازم نیست برای اشک‌هایتان از کسی پوزش بخواهید. ایمان شما کم نیست. شما فقط در عشق زخم خورده‌اید.</p><p class="pl-quote-soft">اگر بخواهید، می‌توانید این‌گونه دعا کنید:</p></section><div class="pl-quote"><p>«خداوندا، می‌دانی چند بار گریه کرده‌ام.<br>سپاسگزارم که مرا به بهبود سریع فشار نمی‌آوری و هر اشک را در ظرف خود نگه می‌داری.<br>همان‌طور که به هر دل شکسته نزدیک می‌شوی، به من هم نزدیک شو؛<br>مرا شفا بده و از آن که دلتنگش هستم مراقبت کن.<br>امروز نمی‌خواهم قوی باشم. فقط می‌خواهم تو در آغوشم بگیری. آمین.»</p></div><section class="pl-section"><h2>چهار کار که اکنون می‌توانید برای خود انجام دهید</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🌊</span><h3>در اوج احساس تصمیم نگیرید</h3><p>موج اندوه می‌گذرد. در سخت‌ترین لحظه، فقط زنده ماندن تا پنج دقیقه بعد کافی است. چیز دیگری را حل نکنید.</p></div><div class="pl-moment"><span class="pl-moment-icon">🍽️</span><h3>نخست از بدن مراقبت کنید</h3><p>آب بنوشید. چیزی بخورید. کمی بخوابید. سوگ بدن را فرسوده می‌کند و بدن گرسنه، درد دل را بیشتر می‌کند.</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>او را در دفتری بنویسید</h3><p>لازم نیست زیبا باشد. یک جزئیات بنویسید: چگونه بیدارتان می‌کرد، کدام حالتش را بیشتر دوست داشتید. به دلتنگی جایی برای ماندن بدهید.</p></div><div class="pl-moment"><span class="pl-moment-icon">🤝</span><h3>کسی را پیدا کنید که واقعاً می‌فهمد</h3><p>همه گریه برای یک حیوان را نمی‌فهمند، اما بعضی می‌فهمند. اگر کسی نبود، بنویسید — خدا می‌تواند بخواند.</p></div></div></section><section class="pl-section"><h2>آن روز خواهد آمد</h2><p>مکاشفه وعده می‌دهد که روزی خدا خودش هر اشکی را از چشمان ما پاک می‌کند و دیگر مرگ، اندوه، فریاد و درد نخواهد بود (مکاشفه ۲۱:۴). در آن روز خواهید دید که هر اشکی که برای او ریختید، هم به یاد مانده و هم از سوی خدایی مهربان پاسخ گرفته است.</p><p>تا آن روز — به خودتان اجازه اندوه بدهید. این هم راهی دیگر برای همچنان دوست داشتن اوست.</p><p><a href="/fa/pets-in-heaven/">← بازگشت به Pets in Heaven</a> ｜ نوشته اول: <a href="/fa/pets-in-heaven/will-i-see-my-pet-again">آیا دوباره او را خواهم دید؟</a></p></section><div class="pl-cta"><h2>امروز، یک جمله کافی است.</h2><p>PetLoss شامل دفترچه راهنما و همراه SOS است که در سنگین‌ترین لحظات کلمات آرام‌بخش می‌دهد. بدون حساب، بدون بارگذاری، کاملاً آفلاین.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">دانلود از App Store</a></div><div class="pl-bible"><h3>بگذارید کلام خدا همراهتان بماند</h3><p>همهٔ آیات این نوشته از کتاب مقدس است. با اپلیکیشن Rainbow Bible می‌توانید هر زمان کتاب مقدس را بخوانید و ویجت «آیهٔ روز» را تنظیم کنید — نوری کوچک برای روزهایی که دلتان تنگ است.</p><div class="pl-bible-shots"><figure><img src="'+a+'" alt="ابزارک Rainbow Bible، آیهٔ ۲ تیموتائوس ۲:۱۳" loading="lazy"><figcaption>آیهٔ روز روی صفحهٔ اصلی</figcaption></figure><figure><img src="'+i+'" alt="اپ Rainbow Bible — موضوع حیوانات خانگی در بهشت، متی ۱۰:۲۹-۳۱" loading="lazy"><figcaption>در موضوع «حیوانات خانگی در بهشت» بخوانید</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">دریافت Rainbow Bible از App Store</a></div>',9)])])}const v=t(n,[["render",l]]);export{b as __pageData,v as default};
